Algorithm Till
  Dimension names[5] As String;
  Dimension prices[5] As Integer;
  Dimension units[5] As Integer;
  names[0] <- "Juice";
  names[1] <- "Sandwich";
  names[2] <- "Cookie";
  names[3] <- "Water";
  names[4] <- "Fruit";
  prices[0] <- 3;
  prices[1] <- 5;
  prices[2] <- 2;
  prices[3] <- 1;
  prices[4] <- 2;
  For i <- 0 To 4 Do
    units[i] <- 0;
  EndFor
  Define total As Integer <- 0;
  Define code As Integer;
  Define amount As Integer;
  Read code;
  While code <> 0 Do
    Read amount;
    If code < 1 Or code > 5 Then
      Write "Code ", code, " does not exist";
    Else
      Define lineTotal As Integer <- prices[code - 1] * amount;
      Write names[code - 1], " x ", amount, " = ", lineTotal;
      total <- total + lineTotal;
      units[code - 1] <- units[code - 1] + amount;
    EndIf
    Read code;
  EndWhile
  Write "Total: ", total;
  Write "With discount: ", total - total Div 10;
  Define best As Integer <- -1;
  For i <- 0 To 4 Do
    If units[i] > 0 Then
      If best = -1 Then
        best <- i;
      Else
        If units[i] > units[best] Then
          best <- i;
        EndIf
      EndIf
    EndIf
  EndFor
  If best = -1 Then
    Write "Best seller: Nobody";
  Else
    Write "Best seller: ", names[best];
  EndIf
EndAlgorithm
